// === Tab: mySketch.js ===
/* Copyright Sebastien LOVERGNE (@TheBigRoomXXL) 2025

**Texture is data, so data can also be a texture doesn't it?**

This script operates in two stages.

First, it runs a particle simulation in a vector field where the force applied at any point is 
defined as:

```
f(x, y) = vec2(cos(x), sin(y))
```

The use of sine and cosine functions makes the system inherently cyclical.

The simulation is implemented using a form of GPGPU (General-Purpose computing on Graphics 
Processing Units). All particle data is stored in a texture, with each pixel encoding one particle:
 - red   = position.x
 - green = position.y
 - blue  = speed.x
 - alpha = speed.y 

A fragment shader computes the next state (N+1) of each particle from the previous state (N). Because
WebGL cannot write to the same texture it reads from, the simulation uses a double-buffering 
approach: one texture stores the current state, and another stores the next state.

The simulation currently runs on a 32×32 grid, for a total of 1024 particles. I deliberately chose 
this low resolution because I find it visually more appealing. While a simulation of this size could
easily run on the CPU with a decent frame rate, using the GPU ensures consistently smooth rendering
across a wide range of devices, including phones, Raspberry Pi boards, and older laptops. This was 
really a goal as I want my art to be accessible.  

> The simulation is efficient enough to compute several million particles at 60 FPS on a modern laptop.

The second stage renders the simulation data. Typically, this would be done by sending one vertex per
particle and using a vertex shader to map each particle’s position—read from the texture—to screen space.
That approach would produce a conventional particle simulation.

Instead, I chose to render the raw simulation data directly as an image. Since the data already exists as
a texture, this simply involves displaying it on screen. To make the result more visually interesting, I
applied a dot filter, which complements the pixelated nature of the rendering. 

To ensure it is accessible on any device the rendering is also responsive to screen size. 

*/

const TEXTURE_SIZE = 48;
const PARTICLE_COUNT = TEXTURE_SIZE * TEXTURE_SIZE;
const DOT_SIZE = 0.01;
const DT = 0.012;
const ZOOM = 28

let simulationShader;
let dotFilter;

let next;
let prev;

let up;
let down;
let left;
let right;

const simulationVertexShader = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec4 aVertexColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec2 vTexCoord;


void main() {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;
  vTexCoord = aTexCoord.xy  ;
}
`

const simulationFragmentShader = `
precision highp float;

uniform sampler2D u_data;
uniform float u_texture_size;
uniform float u_dt;

varying vec2 vTexCoord;

void main() {
    vec4 particule = texture2D(u_data, vTexCoord);

    vec2 position = particule.xy;
    vec2 velocity = particule.zw;

    vec2 acceleration = vec2(cos(position.x), sin(position.y));
    velocity += acceleration * u_dt;
    position += velocity * u_dt;
    position = fract(position);

    gl_FragColor = vec4(position, velocity);
}
`

// Adapted p5.FIP (Fast Image Processing) by prontopablo 
// Original code licenced as MIT
// https://github.com/prontopablo/p5.FIP
const dotFragmentShader = `
precision highp float;

varying vec2 vTexCoord;

uniform sampler2D tex0;
uniform float dotSize;
uniform float u_aspect;

void main() {
    // Create a scaled coordinate system for the dots to keep them round
    vec2 tc = vec2(vTexCoord.x * u_aspect, vTexCoord.y);

    // Calculate the center of the dot in this scaled space
    vec2 dotCoord = floor(tc / dotSize) * dotSize;
    vec2 dotCenter = dotCoord + dotSize * 0.5;

    // Calculate distance for the circular mask (remains round)
    float distanceToCenter = distance(tc, dotCenter);
    float circularPattern = smoothstep(1.0, 0.75, distanceToCenter / (dotSize * 0.5));

    // 4 Map the dotCenter BACK to 0.0-1.0 range for texture sampling
    vec2 sampleCoord = vec2(dotCenter.x / u_aspect, dotCenter.y);

    // Sample the texture using the normalized coordinate
    vec4 dotColor = texture2D(tex0, sampleCoord);

    vec4 white = vec4(1.0);
    gl_FragColor = mix(white, dotColor, circularPattern);
}
`;


function initSimulation(buffer) {
  let img = createImage(TEXTURE_SIZE, TEXTURE_SIZE);
  img.loadPixels();
  for (let i = 0; i < img.pixels.length; i += 4) {
    img.pixels[i] = random(255);      // Pos X
    img.pixels[i + 1] = random(255);  // Pos Y
    img.pixels[i + 2] = 255;          // Vel X
    img.pixels[i + 3] = 255;          // Vel Y
  }
  img.updatePixels();
  buffer.begin();
  image(img, -TEXTURE_SIZE / 2, -TEXTURE_SIZE / 2);
  buffer.end();
}


function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  pixelDensity(2) // fix difference between displays

  // Some phones lock at 30 fps because of the screen refresh rate   
  //  So we target 30 fps to ensure concistant simulation speed.
  frameRate(30)

  // Init Simuation shader and buffers
  simulationShader = createShader(simulationVertexShader, simulationFragmentShader);
  simulationShader.setUniform("u_texture_size", TEXTURE_SIZE);

  prev = createFramebuffer({
    width: TEXTURE_SIZE,
    height: TEXTURE_SIZE,
    textureFiltering: NEAREST,
  });

  next = createFramebuffer({
    width: TEXTURE_SIZE,
    height: TEXTURE_SIZE,
    textureFiltering: NEAREST,
  });

  initSimulation(next);

  // Init dot filter
  dotFilter = createFilterShader(dotFragmentShader)
  dotFilter.setUniform('dotSize', DOT_SIZE); 
  dotFilter.setUniform('u_aspect', windowWidth / windowHeight);

  // Init coordinate (center is the center in webgl mode)
  up = -windowHeight / 2;
  down = windowHeight / 2;
  left = -windowWidth / 2;
  right = windowWidth / 2;

	//saveGif('simulation-loop.gif',10)
}

function draw() {
  // Swap prev and next
  [prev, next] = [next, prev];

  // Compute a new simulation step
  next.begin();

  clear();
  shader(simulationShader);
  simulationShader.setUniform("u_dt", DT);
  simulationShader.setUniform("u_data", prev);
  noStroke();
  rect(-TEXTURE_SIZE / 2, -TEXTURE_SIZE / 2, TEXTURE_SIZE, TEXTURE_SIZE);
  resetShader();

  next.end();

  // Render the simulation data
  const imageSize = TEXTURE_SIZE * ZOOM
  const cols = Math.ceil(windowWidth / imageSize);
  const rows = Math.ceil(windowHeight / imageSize);

  for (let row = 0; row < rows; row++) {
	for (let col = 0; col < cols; col++) {
	  const x = left + col * imageSize - col*ZOOM;
	  const y = up + row * imageSize - row*ZOOM;

	  // Determine flip factors
	  let scaleX = (col % 2 !== 0) ? -1 : 1;
	  let scaleY = (row % 2 !== 0) ? -1 : 1;

	  push();
	  // 1. Move to the center of the current tile
	  translate(x + imageSize / 2, y + imageSize / 2);

	  // 2. Apply both horizontal and vertical scaling
	  scale(scaleX, scaleY);

	  // 3. Draw image centered on the translation point
	  image(next, -imageSize / 2, -imageSize / 2, imageSize, imageSize);
	  pop();
	}
	}
  // image(next, left, up, TEXTURE_SIZE * ZOOM,TEXTURE_SIZE * ZOOM);
  filter(dotFilter);
}

